                    JsonSerializer.Serialize(writer, ownedMediaSummaryResponse.Platforms, jsonSerializerOptions);
                }
                else
                    writer.WriteNull("platforms");
            if (ownedMediaSummaryResponse.RequestIdOption.IsSet)
                writer.WriteString("request_id", ownedMediaSummaryResponse.RequestId);
        }
    }
}
